sp_widget.client_script:
api.controller=function($scope) {
    var c = this;
    c.setSection1Visible = function() {
        var g_form = $scope.page.g_form;
        g_form.setValue('current_section','1');
    }
        c.setSection2Visible = function() {
        var g_form = $scope.page.g_form;
        g_form.setValue('current_section','2');
    }
        c.setSection3Visible = function() {
        var g_form = $scope.page.g_form;
        g_form.setValue('current_section','3');
    }
        c.setSection4Visible = function() {
        var g_form = $scope.page.g_form;
        g_form.setValue('current_section','4');
    }
        c.setSection5Visible = function() {
        var g_form = $scope.page.g_form;
        g_form.setValue('current_section','5');
    }
	c.isActive = function(step) {
		var g_form = $scope.page.g_form;
    return g_form.getValue('current_section') == step;
  };
};

sp_widget.css:
.btn-breadcrumb .btn:not(:last-child):after {
  content: " ";
  display: block;
  width: 0;
  height: 0;
  border-top: 17px solid transparent;
  border-bottom: 17px solid transparent;
  border-left: 10px solid white;
  position: absolute;
  top: 50%;
  margin-top: -17px;
  left: 100%;
  z-index: 3;
}
.btn-breadcrumb .btn:not(:last-child):before {
  content: " ";
  display: block;
  width: 0;
  height: 0;
  border-top: 17px solid transparent;
  border-bottom: 17px solid transparent;
  border-left: 10px solid rgb(173, 173, 173);
  position: absolute;
  top: 50%;
  margin-top: -17px;
  margin-left: 1px;
  left: 100%;
  z-index: 3;
}
/** The Spacing **/
.btn-breadcrumb .btn {
  padding:6px 12px 6px 24px;
  font-size:16px;
}
.btn-breadcrumb .btn:first-child {
  padding:6px 6px 6px 10px;
}
.btn-breadcrumb .btn:last-child {
  padding:6px 18px 6px 24px;
}
/** Default button **/
.btn-breadcrumb .btn.btn-default:not(:last-child):after {
  border-left: 10px solid #fff;
}
.btn-breadcrumb .btn.btn-default:not(:last-child):before {
  border-left: 10px solid #ccc;
}
.btn-breadcrumb .btn.btn-default:hover:not(:last-child):after {
  border-left: 10px solid #EBEBEB;
}
.btn-breadcrumb .btn.btn-default:hover:not(:last-child):before {
  border-left: 10px solid #ADADAD;
}
/** Active Section Color **/
.active-section {
  background-color: #0073E6 !important;
  color: white !important;
}
.btn-breadcrumb a.active-section::after {
  color: #0073E6 !important;
  border-left-color: #0073E6 !important;
}
